1	import { Component, computed, effect, inject, input, signal, untracked } from '@angular/core';
2	import { DecimalPipe } from '@angular/common';
3	import type { Subscription } from 'rxjs';
4	
5	import { ProductDetail as ProductDetailModel, ProductsApi } from '../../core/api/products.api';
6	import { CartService } from '../cart/cart.service';
7	
8	@Component({
9	  selector: 'app-product-detail',
10	  imports: [DecimalPipe],
11	  templateUrl: './product-detail.html',
12	  styleUrl: './product-detail.scss',
13	})
14	export class ProductDetail {
15	  private readonly productsApi = inject(ProductsApi);
16	  private readonly cartService = inject(CartService);
17	  private subscription: Subscription | undefined;
18	
19	  readonly id = input.required<string>();
20	
21	  protected readonly product = signal<ProductDetailModel | null>(null);
22	  protected readonly loading = signal(false);
23	  protected readonly notFound = signal(false);
24	  protected readonly error = signal(false);
25	
26	  protected readonly ratingAuthorName = signal('');
27	  protected readonly ratingValue = signal(5);
28	  protected readonly ratingSubmitting = signal(false);
29	  protected readonly ratingError = signal<string | null>(null);
30	
31	  protected readonly selectedSupplierId = signal<string | null>(null);
32	  protected readonly quantity = signal(1);
33	  protected readonly addedToCartMessage = signal<string | null>(null);
34	
35	  protected readonly canAddToCart = computed(() => {
36	    const supplierId = this.selectedSupplierId();
37	    const quantity = this.quantity();
38	    return supplierId !== null && Number.isInteger(quantity) && quantity >= 1;
39	  });
40	
41	  constructor() {
42	    effect((onCleanup) => {
43	      const id = this.id();
44	      this.loadProduct(id);
45	      onCleanup(() => this.subscription?.unsubscribe());
46	    });
47	  }
48	
49	  private loadProduct(id: string, options: { resetFirst: boolean } = { resetFirst: true }): void {
50	    if (options.resetFirst) {
51	      this.product.set(null);
52	      this.notFound.set(false);
53	      this.error.set(false);
54	      this.selectedSupplierId.set(null);
55	      this.quantity.set(1);
56	      this.addedToCartMessage.set(null);
57	      this.ratingAuthorName.set('');
58	      this.ratingValue.set(5);
59	      this.ratingSubmitting.set(false);
60	      this.ratingError.set(null);
61	    }
62	    this.loading.set(true);
63	    this.subscription?.unsubscribe();
64	    this.subscription = this.productsApi.getProduct(id).subscribe({
65	      next: (product) => {
66	        if (this.id() !== id) {
67	          return;
68	        }
69	        this.product.set(product);
70	        const stillOffered = untracked(() => product.offers.some((o) => o.supplierId === this.selectedSupplierId()));
71	        if (!stillOffered) {
72	          this.selectedSupplierId.set(product.offers[0]?.supplierId ?? null);
73	          this.addedToCartMessage.set(null);
74	        }
75	        this.loading.set(false);
76	      },
77	      error: (err) => {
78	        if (this.id() !== id) {
79	          return;
80	        }
81	        this.loading.set(false);
82	        if (err?.status === 404) {
83	          this.notFound.set(true);
84	        } else {
85	          this.error.set(true);
86	        }
87	      },
88	    });
89	  }
90	
91	  protected submitRating(): void {
92	    const id = this.id();
93	    this.ratingSubmitting.set(true);
94	    this.ratingError.set(null);
95	    this.productsApi.submitRating(id, this.ratingAuthorName(), this.ratingValue()).subscribe({
96	      next: () => {
97	        if (this.id() !== id) {
98	          return;
99	        }
100	        this.ratingSubmitting.set(false);
101	        this.ratingAuthorName.set('');
102	        this.loadProduct(id, { resetFirst: false });
103	      },
104	      error: () => {
105	        if (this.id() !== id) {
106	          return;
107	        }
108	        this.ratingSubmitting.set(false);
109	        this.ratingError.set('Bewertung konnte nicht gespeichert werden. Bitte überprüfen Sie Ihre Eingabe.');
110	      },
111	    });
112	  }
113	
114	  protected addToCart(): void {
115	    const product = this.product();
116	    const supplierId = this.selectedSupplierId();
117	    const quantity = this.quantity();
118	    if (product === null || supplierId === null || !Number.isInteger(quantity) || quantity < 1) {
119	      return;
120	    }
121	    const offer = product.offers.find((o) => o.supplierId === supplierId);
122	    if (offer === undefined) {
123	      return;
124	    }
